def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r in range(h):
        if all(v == bg for v in grid[r]):
            out[r] = [2] * w
    for c in range(w):
        if all(grid[r][c] == bg for r in range(h)):
            for r in range(h):
                out[r][c] = 2
    return out

